                parsed &&
                uuid != UUIDHelpers::Nil &&
                uuid_str.starts_with(prefix);

            if (!expected_dir)
            {
                LOG_WARNING(log, "Found invalid directory {}, will try to remove it", uuid_dir.path().string());
                affected_dirs += maybeRemoveDirectory(uuid_dir.path());
