    }

    if (affected_dirs)
        LOG_INFO(log, "Cleaned up {} directories from store/", affected_dirs);
    else
        LOG_TEST(log, "Nothing to clean up from store/");

    (*cleanup_task)->scheduleAfter(unused_dir_cleanup_period_sec * 1000);
}

